// ValidatePlacementInputRequestBody runs the validations defined on
// PlacementInputRequestBody
func ValidatePlacementInputRequestBody(body *PlacementInputRequestBody) (err error) {
	if body.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "body"))
	}
	if body.WidgetID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("widget_id", "body"))
	}
	if body.X == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("x", "body"))
	}
	if body.Y == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("y", "body"))
	}
	if body.W == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("w", "body"))
	}
	if body.H == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("h", "body"))
	}
	if body.ID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.id", *body.ID, goa.FormatUUID))
	}
	if body.WidgetID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.widget_id", *body.WidgetID, goa.FormatUUID))
	}
	if body.X != nil {
		if *body.X < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.x", *body.X, 0, true))
		}
	}
	if body.X != nil {
		if *body.X > 11 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.x", *body.X, 11, false))
		}
	}
	if body.Y != nil {
		if *body.Y < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.y", *body.Y, 0, true))
		}
	}
	if body.Y != nil {
		if *body.Y > 9999 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.y", *body.Y, 9999, false))
		}
	}
	if body.W != nil {
		if *body.W < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.w", *body.W, 1, true))
		}
	}
	if body.W != nil {
		if *body.W > 12 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.w", *body.W, 12, false))
		}
	}
	if body.H != nil {
		if *body.H < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.h", *body.H, 1, true))
		}
	}
	if body.H != nil {
		if *body.H > 10000 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.h", *body.H, 10000, false))
		}
	}
	return
}

